vec4 effect(vec2 uv) {
  float band = fract(uTime * 0.25);
  float inBand = smoothstep(0.08, 0.0, abs(uv.y - (1.0 - band)));
  vec2 u = uv;
  u.x += (noise(vec2(uv.y * 80.0, uTime * 20.0)) - 0.5) * 0.06 * inBand * uAmount;
  vec3 c = vec3(getColor(u + vec2(0.004, 0.0)).r, getColor(u).g, getColor(u - vec2(0.004, 0.0)).b);
  c += vec3(hash(vec2(uv.y * 400.0, uTime))) * inBand * 0.4 * uAmount;
  c += step(0.997, hash(vec2(floor(uv.y * 240.0), floor(uTime * 30.0)))) * 0.5 * uAmount;
  return vec4(c, getColor(uv).a);
}
